import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

from collections import Counter
def f(g):
    g=[r[:] for r in g]; bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*len(g[0]) for _ in g]
    for i in range(len(g)):
        for j in range(len(g[0])):
            c=g[i][j]
            if c==bg or seen[i][j]: continue
            # extent
            hi=[x for x in range(len(g)) if g[x][j]==c]; lo=[x for x in range(len(g)) if g[x][j]==c]
            h0=min(hi); h1=max(hi); w0=min(x for x in range(len(g[0])) if g[i][x]==c); w1=max(x for x in range(len(g[0])) if g[i][x]==c)
            for x in range(h0+1,h1):
                for y in range(w0+1,w1):
                    if g[x][y]==c: seen[x][y]=True; g[x][y]=2
    return g

